import re, json

# Check: for the 32 FN cases on val, is the last number in the full output == gold?
# And does the 300-char clip lose it?
def full_last_num(text):
    nums = re.findall(r'(\-?[0-9\.\,]+)', text)
    for a in reversed(nums):
        if a not in ('', '.'):
            return a
    return None

with open('/workspace/results/grpo_gsm8k/val_generations/50.jsonl') as f:
    rows = [json.loads(l) for l in f]

fn = 0
for i, d in enumerate(rows):
    if d['score'] == 0:
        fln = full_last_num(d['output'])
        if fln is not None:
            # strip trailing period, try float
            fn_clean = fln.rstrip('.')
            try:
                if float(fn_clean) == float(d['gts']):
                    fn += 1
            except: pass

print(f'FN where full last number (float) == gold: {fn}')
# categorize: how many are due to 300-char clip vs trailing period vs cents
clipped = 0
trailing_period = 0
cents = 0
for i, d in enumerate(rows):
    if d['score'] == 0:
        fln = full_last_num(d['output'])
        if fln is not None:
            fn_clean = fln.rstrip('.')
            try:
                if float(fn_clean) == float(d['gts']):
                    # check cause
                    if len(d['output']) > 300:
                        tail300 = d['output'][-300:]
                        nums300 = [a for a in re.findall(r'(\-?[0-9\.\,]+)', tail300) if a not in ('', '.')]
                        if fln not in nums300:
                            clipped += 1
                    if fln.endswith('.'):
                        trailing_period += 1
                    if '.' in fln and fln != fln.rstrip('0').rstrip('.'):
                        # e.g., 12.00
                        pass
                        # but we already count these in the FN total
print(f'  due to 300-char clip: {clipped}')
print(f'  with trailing period: {trailing_period}')
print(f'  with decimal (.00 etc): any remaining')
" 2>&1

