import re, json

# Simulate the fix
def extract_solution_fixed(solution_str, method="flexible"):
    if len(solution_str) > 300:
        solution_str = solution_str[-300:]

    if method == "strict":
        solutions = re.findall("#### (\\-?[0-9\\.\\,]+)", solution_str)
        if len(solutions) == 0:
            return None
        return solutions[-1].replace(",", "").replace("$", "")
    else:
        answer = re.findall("(\\-?[0-9\\.\\,]+)", solution_str)
        final_answer = None
        if len(answer) == 0:
            pass
        else:
            invalid_str = ["", "."]
            for final_answer in reversed(answer):
                if final_answer not in invalid_str:
                    break
        if final_answer is not None:
            final_answer = final_answer.rstrip('.').replace('$', '').replace(',', '')
        return final_answer

def compute_score_fixed(solution_str, ground_truth, method="flexible"):
    answer = extract_solution_fixed(solution_str, method=method)
    if answer is None:
        return 0
    try:
        if abs(float(answer) - float(ground_truth)) < 1e-6:
            return 1.0
    except (ValueError, TypeError):
        pass
    return 0.0

# Load val dump and compare
with open('/workspace/results/grpo_gsm8k/val_generations/50.jsonl') as f:
    rows = [json.loads(l) for l in f]

# Also compute grader rule
def grader_score(output, gt):
    nums = re.findall(r'(-?\d[\d,]*(?:\.\d+)?)', output)
    if not nums:
        return None
    last = nums[-1].replace(',', '')
    try:
        return 1.0 if float(last) == float(gt) else 0.0
    except:
        return None

old_fn = 0
old_fp = 0
new_fn = 0
new_fp = 0
grader_agree_old = 0
grader_agree_new = 0

for d in rows:
    old_score = d['score']
    new_score = compute_score_fixed(d['output'], d['gts'])
    g = grader_score(d['output'], d['gts'])

    # vs grader
    if old_score != g: 
        if old_score == 0: old_fn += 1
        else: old_fp += 1
    else:
        grader_agree_old += 1

    if new_score != g:
        if new_score == 0: new_fn += 1
        else: new_fp += 1
    else:
        grader_agree_new += 1

print(f"Old reward vs grader: FN={old_fn}, FP={old_fp}, agree={grader_agree_old}/{len(rows)}")
print(f"New reward vs grader: FN={new_fn}, FP={new_fp}, agree={grader_agree_new}/{len(rows)}")
print()

# Also check on rollouts
for step in ['1','25','50']:
    with open(f'/workspace/results/grpo_gsm8k/rollouts/{step}.jsonl') as f:
        rrows = [json.loads(l) for l in f]
    old_fn = old_fp = new_fn = new_fp = 0
    for d in rrows:
        old_score = d.get('score')
        new_score = compute_score_fixed(d['output'], d['gts'])
